package main

import (
	"encoding/json"
	"flag"
	"fmt"
	"os"
	"os/exec"
	"strings"

	"github.com/KogenAI/kogen-build/build"
	"github.com/KogenAI/kogen-coordinator/git"
	"github.com/KogenAI/kogen-loop/provider"
	"github.com/KogenAI/kogen-loop/sys"
	"github.com/KogenAI/kogen-verification/verify"
)

const usageForms = "expected build --project <checkout> --slug <slug> or resume --project <checkout> --id <build-id>"

type problem struct {
	Category string `json:"category"`
	Kind     string `json:"kind"`
	Message  string `json:"message"`
}
type result struct {
	ExitCode int                    `json:"exit_code"`
	Branch   string                 `json:"branch"`
	Tree     string                 `json:"tree"`
	Checks   []verify.CommandResult `json:"checks"`
	Error    *problem               `json:"error"`
}

func main() {
	sys.MaybeSupervise(os.Args[1:])
	sys.EnableSupervisor()
	os.Exit(run())
}
func run() int {
	s := sys.New()
	s.Stdout = os.Stderr
	stop := s.WatchSignals()
	defer stop()
	r := result{Checks: []verify.CommandResult{}}
	defer func() { _ = json.NewEncoder(os.Stdout).Encode(r) }()
	refuse := func(message string) int {
		r.ExitCode = 2
		r.Error = &problem{"usage", "invalid_arguments", message}
		return r.ExitCode
	}
	if len(os.Args) < 2 {
		return refuse("expected build or resume")
	}
	mode := os.Args[1]
	if mode != "build" && mode != "resume" {
		return refuse(fmt.Sprintf("unknown mode %q: %s", mode, usageForms))
	}
	flags := flag.NewFlagSet(mode, flag.ContinueOnError)
	flags.SetOutput(os.Stderr)
	project := flags.String("project", ".", "checkout")
	slug := flags.String("slug", "", "intent slug")
	id := flags.String("id", "", "build ID")
	if err := flags.Parse(os.Args[2:]); err != nil {
		return refuse(fmt.Sprintf("%v: %s", err, usageForms))
	}
	if flags.NArg() != 0 {
		return refuse(fmt.Sprintf("unexpected argument %q: %s", flags.Arg(0), usageForms))
	}
	if mode == "build" && *slug == "" {
		return refuse("missing required --slug: " + usageForms)
	}
	if mode == "resume" && *id == "" {
		return refuse("missing required --id: " + usageForms)
	}
	cmd := exec.Command("git", "-C", *project, "symbolic-ref", "--quiet", "--short", "HEAD")
	b, _ := cmd.Output()
	r.Branch = strings.TrimSpace(string(b))
	if repo, e := git.Open(*project, s.Env); e == nil {
		r.Tree, _ = repo.Tree(repo.Head(), nil)
	}
	out := build.Outcome{}
	deps := build.Deps{Client: provider.NewClient("kogen-build"), Tools: verify.Tools{Node: os.Getenv("KOGEN_NODE"), Quint: os.Getenv("KOGEN_QUINT"), Cucumber: os.Getenv("KOGEN_CUCUMBER")}, Outcome: &out}
	var err error
	if mode == "build" {
		r.ExitCode, err = build.Build(s.Context(), s, build.Input{Deps: deps, Project: *project, Slug: *slug})
	} else {
		r.ExitCode, err = build.Resume(s.Context(), s, build.ResumeInput{Deps: deps, Project: *project, ID: *id})
	}
	if out.Tree != "" {
		r.Tree = out.Tree
	}
	r.Checks = out.Checks
	if out.Error != nil {
		r.Error = &problem{out.Error.Class, out.Error.Reason, out.Error.Detail}
	} else if err != nil {
		r.Error = &problem{"internal", "error", err.Error()}
	}
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
	}
	return r.ExitCode
}

